t.script:
document.addEventListener('DOMContentLoaded', function() {
    // Sidebar Toggle
    var sidebarToggle = document.querySelector('.mp-sidebar-toggle');
    var sidebar = document.querySelector('.mp-sidebar');
    if (sidebarToggle && sidebar) {
        sidebarToggle.addEventListener('click', function() {
            sidebar.classList.toggle('collapsed');
        });
    }

    // Mobile Menu Toggle
    var mobileToggle = document.querySelector('.mp-mobile-menu-toggle');
    var overlay = document.querySelector('.mp-sidebar-overlay');
    if (mobileToggle && sidebar) {
        mobileToggle.addEventListener('click', function() {
            sidebar.classList.toggle('mobile-open');
            overlay?.classList.toggle('active');
        });
    }
    if (overlay) {
        overlay.addEventListener('click', function() {
            sidebar?.classList.remove('mobile-open');
            this.classList.remove('active');
        });
    }
});

document.addEventListener('DOMContentLoaded', function() {
    if (typeof ApexCharts === 'undefined') {
        console.log('ApexCharts not loaded');
        return;
    }

    // Revenue Chart
    var revenueEl = document.getElementById('mp-revenue-chart');
    if (revenueEl) {
        var chartData = ;

        var revenueOptions = {
            series: [{
                name: 'Expected Revenue',
                data: chartData.revenue ? chartData.revenue.revenue : []
            }, {
                name: 'Collected',
                data: chartData.revenue ? chartData.revenue.collected : []
            }],
            chart: {
                type: 'area',
                height: 300,
                toolbar: { show: false },
                fontFamily: 'inherit'
            },
            colors: ['#5C6BC0', '#66BB6A'],
            fill: {
                type: 'gradient',
                gradient: { shadeIntensity: 1, opacityFrom: 0.4, opacityTo: 0.1 }
            },
            stroke: { curve: 'smooth', width: 3 },
            dataLabels: { enabled: false },
            xaxis: {
                categories: chartData.revenue ? chartData.revenue.months : [],
                labels: { style: { colors: '#78909C' } }
            },
            yaxis: {
                labels: {
                    style: { colors: '#78909C' },
                    formatter: function(val) { return val.toLocaleString(); }
                }
            },
            grid: { borderColor: '#E0E0E0', strokeDashArray: 4 },
            legend: { position: 'top', horizontalAlign: 'right' },
            tooltip: { y: { formatter: function(val) { return val.toLocaleString() + ' ﷼'; } } }
        };
        new ApexCharts(revenueEl, revenueOptions).render();
    }

    // Units Distribution Chart
    var unitsEl = document.getElementById('mp-units-chart');
    if (unitsEl) {
        var available = ;
        var rented = ;
        var reserved = ;

        var unitsOptions = {
            series: [available, rented, reserved],
            labels: ['Available', 'Rented', 'Reserved'],
            chart: { type: 'donut', height: 300 },
            colors: ['#66BB6A', '#FFA726', '#42A5F5'],
            plotOptions: {
                pie: {
                    donut: {
                        size: '70%',
                        labels: {
                            show: true,
                            name: { show: true, fontSize: '14px' },
                            value: { show: true, fontSize: '20px', fontWeight: 700 },
                            total: { show: true, label: 'Total Units', fontSize: '12px' }
                        }
                    }
                }
            },
            legend: { position: 'bottom' },
            dataLabels: { enabled: false }
        };
        new ApexCharts(unitsEl, unitsOptions).render();
    }

    // Property Search Filter
    var searchInput = document.getElementById('property-search');
    if (searchInput) {
        searchInput.addEventListener('input', function() {
            var filter = this.value.toLowerCase();
            var rows = document.querySelectorAll('.property-row');
            rows.forEach(function(row) {
                var text = row.textContent.toLowerCase();
                row.style.display = text.includes(filter) ? '' : 'none';
            });
        });
    }

    // Units Search Filter
    var unitSearchInput = document.getElementById('unit-search');
    if (unitSearchInput) {
        unitSearchInput.addEventListener('input', function() {
            filterUnits();
        });
    }

    // Units Status Filter
    var unitStatusFilter = document.getElementById('unit-status-filter');
    if (unitStatusFilter) {
        unitStatusFilter.addEventListener('change', function() {
            filterUnits();
        });
    }

    function filterUnits() {
        var searchFilter = (document.getElementById('unit-search')?.value || '').toLowerCase();
        var statusFilter = document.getElementById('unit-status-filter')?.value || '';
        var rows = document.querySelectorAll('.unit-row');

        rows.forEach(function(row) {
            var text = row.textContent.toLowerCase();
            var status = row.getAttribute('data-status') || '';

            var matchesSearch = !searchFilter || text.includes(searchFilter);
            var matchesStatus = !statusFilter || status === statusFilter || 
                               (statusFilter === 'rented' && (status === 'rented' || status === 'on_lease'));

            row.style.display = (matchesSearch && matchesStatus) ? '' : 'none';
        });
    }
});
